-- Add gateway (meta MCP) attribution columns before emission ships so no row misses them
ALTER TABLE `telemetry_logs` ADD COLUMN `meta_mcp_server_id` String MATERIALIZED toString(attributes.gram.meta_mcp_server.id) COMMENT 'Meta MCP server (Gateway Endpoint) ID when the call was dispatched through a gateway (materialized from attributes.gram.meta_mcp_server.id).';
ALTER TABLE `telemetry_logs` ADD INDEX `idx_telemetry_logs_mat_meta_mcp_server_id` ((meta_mcp_server_id)) TYPE bloom_filter(0.01) GRANULARITY 1;
ALTER TABLE `trace_summaries` ADD COLUMN `meta_mcp_server_id` SimpleAggregateFunction(max, String);
-- Hand-edited (not atlas's DROP+recreate): swap the MV SELECT in place with
-- ALTER TABLE ... MODIFY QUERY so there is no ingestion gap.
ALTER TABLE `trace_summaries_mv` MODIFY QUERY SELECT trace_id, gram_project_id, any(gram_deployment_id) AS gram_deployment_id, any(gram_function_id) AS gram_function_id, any(gram_urn) AS gram_urn, any(tool_name) AS tool_name, any(tool_source) AS tool_source, any(event_source) AS event_source, any(user_email) AS user_email, any(hook_source) AS hook_source, any(skill_name) AS skill_name, anyIf(toolset_slug, toolset_slug != '') AS toolset_slug, anyIf(external_user_id, external_user_id != '') AS external_user_id, anyIf(user_id, user_id != '') AS user_id, anyIf(toString(attributes.gram.mcp.match), toString(attributes.gram.mcp.match) != '') AS mcp_match, anyIf(toString(attributes.gram.mcp.server_url), toString(attributes.gram.mcp.server_url) != '') AS mcp_server_url, min(time_unix_nano) AS start_time_unix_nano, toUInt64(count(*)) AS log_count, anyIfState(toInt32OrNull(toString(attributes.http.response.status_code)), toString(attributes.http.response.status_code) != '') AS http_status_code, max(if(toString(attributes.gen_ai.tool.call.result) != '', 1, 0)) AS has_result, max(if(toString(attributes.gram.hook.error) != '', 1, 0)) AS has_error, max(if(toString(attributes.gram.hook.block_reason) != '', 1, 0)) AS has_block, anyIf(toString(attributes.gram.hook.block_reason), toString(attributes.gram.hook.block_reason) != '') AS block_reason, anyIf(account_type, account_type != '') AS account_type, anyIf(provider, provider != '') AS provider, anyIf(meta_mcp_server_id, meta_mcp_server_id != '') AS meta_mcp_server_id FROM telemetry_logs WHERE (trace_id IS NOT NULL) AND (trace_id != '') AND (NOT startsWith(telemetry_logs.gram_urn, 'urn:uuid:')) GROUP BY trace_id, gram_project_id;
